create role anon; create role authenticated; create role service_role;
create schema auth; create schema storage; create schema aud_private;
create table auth.users(id uuid primary key, last_sign_in_at timestamptz, banned_until timestamptz);
create table auth.sessions(id uuid, user_id uuid references auth.users on delete cascade);
create table storage.objects(id uuid default gen_random_uuid(), bucket_id text,name text,owner uuid,owner_id text);
create table aud_private.links (id uuid,audit_id uuid,token_hash text,expires_at timestamp with time zone,revoked_at timestamp with time zone,created_at timestamp with time zone);
create table public.aud_audits (id uuid,farm_id uuid,pharmacy text,cnpj text,reference text,requested integer,deadline date,notes text,collection text,created_by uuid,created_at timestamp with time zone,next_batch integer,max_bytes bigint,retention_days integer,contact_email text,contact_phone text,confirmed_at timestamp with time zone,deleted_at timestamp with time zone,deleted_by uuid);
create table public.aud_batches (id uuid,audit_id uuid,number integer,client_key uuid,manifest jsonb,started_at timestamp with time zone,completed_at timestamp with time zone,protocol text);
create table public.aud_events (id bigint,audit_id uuid,event text,actor_id uuid,entity_id uuid,created_at timestamp with time zone);
create table public.aud_files (id uuid,audit_id uuid,batch_id uuid,source text,created_at timestamp with time zone,filename text,size bigint,mime text,fingerprint text,storage_path text,received_at timestamp with time zone,scan text,verified_sha256 text,scanned_at timestamp with time zone,scan_attempts integer,next_scan_at timestamp with time zone);
create table public.aud_jobs (id uuid,audit_id uuid,batch_id uuid,kind text,status text,created_at timestamp with time zone);
create table public.audit_logs (id uuid,farm_id uuid,user_id uuid,action text,entity_type text,entity_id uuid,metadata jsonb,created_at timestamp with time zone);
create table public.authorizations (id uuid,farm_id uuid,client_id uuid,numero text,status text,created_at timestamp with time zone,data_dispensacao date);
create table public.autorizacoes (id uuid,user_id uuid,numero_autorizacao text,data_autorizacao date,farmacia text,observacao text,created_at timestamp with time zone,updated_at timestamp with time zone,cpf_cliente text,crm text,crm_uf text);
create table public.clients (id uuid,farm_id uuid,nome text,cpf text,created_at timestamp with time zone);
create table public.compras_estoque (farm_id uuid,versao uuid,data_posicao date,arquivo text,itens jsonb,atualizado_em timestamp with time zone,atualizado_por uuid);
create table public.cre_events (id bigint,process_id uuid,action text,created_at timestamp with time zone);
create table public.cre_files (id uuid,process_id uuid,kind integer,filename text,mime text,size bigint,fingerprint text,storage_path text,created_at timestamp with time zone,received_at timestamp with time zone,scan text,scan_attempts integer,scanned_at timestamp with time zone,next_scan_at timestamp with time zone);
create table public.cre_processes (id uuid,owner_id uuid,ficha jsonb,filial boolean,partners integer,revision integer,token_hash text,expires_at timestamp with time zone,created_at timestamp with time zone,updated_at timestamp with time zone,rate_minute timestamp with time zone,rate_count integer);
create table public.dispensacao_itens (id uuid,autorizacao_id uuid,documento_id uuid,posicao integer,produto text,ean text,unidade text,quantidade numeric(15,3),valor_unitario numeric(15,4),valor_total numeric(15,2),valor_pfpb numeric(15,2),principio_ativo text,indicacao text,data_dispensacao date,status text,origens jsonb,created_at timestamp with time zone,updated_at timestamp with time zone);
create table public.document_versions (id uuid,document_id uuid,version integer,storage_path text,original_filename text,mime_type text,file_size bigint,uploaded_by uuid,created_at timestamp with time zone);
create table public.documentos (id uuid,autorizacao_id uuid,categoria text,nome_arquivo text,caminho_arquivo text,status text,created_at timestamp with time zone,updated_at timestamp with time zone);
create table public.documents (id uuid,authorization_id uuid,categoria text,status text,created_at timestamp with time zone);
create table public.farms (id uuid,razao_social text,nome_fantasia text,cnpj text,status text,created_at timestamp with time zone,telefone text,cidade text,estado text);
create table public.invitation_deliveries (attempt_id uuid,audit_id uuid,credential_id uuid,link_hash text,channel text,status text,created_at timestamp with time zone,updated_at timestamp with time zone);
create table public.rbk_admins (user_id uuid,created_at timestamp with time zone,ativo boolean);
create table public.rbk_manager_farms (manager_user_id uuid,farm_id uuid,granted_by uuid,granted_at timestamp with time zone);
create table public.users (id uuid,farm_id uuid,nome text,email text,perfil text,status text,created_at timestamp with time zone,last_access_at timestamp with time zone);
alter table public.farms add primary key(id); alter table public.users add primary key(id); alter table public.users add foreign key(id) references auth.users on delete cascade;
alter table public.users add foreign key(farm_id) references public.farms;

